// GENERATED by `npm run build:functions` from src/online/chatFilter.js. Do not edit.
// Chat filter (DESIGN.md, Safety). The chat Edge Function runs this on every
// message before anyone sees it; supabase/functions/chat/filter.js is a copy
// made by `npm run build:functions`. It must not import anything.
//
// - Hate words, even disguised (sp4ced o.u.t, l33t, look-alike letters,
//   stretched): the message reaches nobody.
// - Crude words: masked with asterisks.
// - Links and contact details (emails, phone numbers, social handles): removed.
// Word lists are ROT13-encoded so the source doesn't spell them out.

export const MAX_LENGTH = 120;

const rot13 = (s) => s.replace(/[a-z]/g, (c) => String.fromCharCode(((c.charCodeAt(0) - 84) % 26) + 97));
const list = (s) => s.split(' ').map(rot13);

// Hate terms matched anywhere, even spaced out or disguised.
const HATE_ANY = list('avttre avttn snttbg jrgonpx enturnq gbjryurnq ergneq uvgyre xvyylbhefrys');
// Hate terms matched as a whole word (they hide inside innocent words).
const HATE_WORD = list('fcvp xvxr puvax tbbx pbba cnxv snt xxx anmv urvy xlf genaal ornare qlxr');
// Crude words masked wherever they appear in a word.
const CRUDE_ANY = list('shpx zbgureshpxre phag ovgpu juber fyhg nffubyr nefrubyr onfgneq jnaxre qvpxurnq pbpxfhpxre ohyyfuvg wvmm qvyqb cbea cravf intvan obyybpxf');
// Crude words masked as a whole word, with common endings.
const CRUDE_WORD = list('fuvg nff nefr qvpx pbpx chffl jnax gjng cvff gvgf phz frk obbof penc');
const ENDINGS = ['', 's', 'es', 'er', 'ers', 'ed', 'ing', 'y', 'ty', 'ey', 'head', 'heads', 'hole', 'holes', 'face'];

// Letters people swap in to dodge filters.
const LEET = { 0: 'o', 1: 'i', 3: 'e', 4: 'a', 5: 's', 6: 'g', 7: 't', 8: 'b', 9: 'g', '@': 'a', $: 's', '!': 'i', '|': 'i', '+': 't', '€': 'e', '£': 'l', '¡': 'i' };
// Look-alike letters from other alphabets.
const LOOKALIKE = { а: 'a', в: 'b', е: 'e', ё: 'e', к: 'k', м: 'm', н: 'h', о: 'o', р: 'p', с: 'c', т: 't', у: 'y', х: 'x', і: 'i', ј: 'j', ѕ: 's', α: 'a', β: 'b', ε: 'e', ι: 'i', κ: 'k', ν: 'v', ο: 'o', ρ: 'p', τ: 't', υ: 'u', χ: 'x' };

const collapse = (s) => s.replace(/(.)\1+/g, '$1');

// Control characters and invisible formatting characters people use to hide words.
function invisible(cp) {
  return cp < 32 || (cp >= 127 && cp <= 159) || (cp >= 8203 && cp <= 8207) || (cp >= 8232 && cp <= 8238) || (cp >= 8288 && cp <= 8303) || cp === 65279;
}

// Lower case, accents off, look-alikes and leetspeak to plain letters.
export function plain(s) {
  return String(s)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/./gu, (c) => LOOKALIKE[c] || LEET[c] || c);
}

const HATE_ANY_C = HATE_ANY.map(collapse);

// A whole-word pattern that also matches stretched spellings ("cooool") but
// never fewer letters than the real word (so "as" isn't "ass").
function stretched(word) {
  const runs = word.match(/(.)\1*/g);
  return runs.map((r) => `${r[0]}{${r.length},}`).join('');
}
const wordPattern = (words, endings = ['']) => new RegExp(`^(?:${words.flatMap((w) => endings.map((e) => stretched(w + e))).join('|')})$`);
const HATE_WORD_RE = wordPattern(HATE_WORD, ['', 's']);
const CRUDE_WORD_RE = wordPattern(CRUDE_WORD, ENDINGS);

// Words as people meant them: "f u c k" and "f.u.c.k" join up into one word.
function tokens(text) {
  const raw = [...String(text).matchAll(/[^\s]+/g)].map((m) => ({ s: m[0], i: m.index }));
  const out = [];
  for (let k = 0; k < raw.length; k++) {
    const t = raw[k];
    const letters = plain(t.s).replace(/[^a-z]/g, '');
    // Runs of single letters (or letters split by dots/dashes) join up.
    if (letters.length === 1 || /^([a-z0-9@$][.\-_*]){2,}[a-z0-9@$]?$/i.test(t.s)) {
      let j = k;
      let joined = '';
      while (j < raw.length) {
        const l = plain(raw[j].s).replace(/[^a-z]/g, '');
        const single = l.length === 1 || /^([a-z0-9@$][.\-_*]){2,}[a-z0-9@$]?$/i.test(raw[j].s);
        if (!single) break;
        joined += l;
        j++;
      }
      if (j - k > 1 || joined.length > 1) {
        out.push({ word: joined, start: t.i, end: raw[j - 1].i + raw[j - 1].s.length });
        k = j - 1;
        continue;
      }
    }
    out.push({ word: letters, start: t.i, end: t.i + t.s.length });
  }
  return out;
}

function hasHate(text) {
  const all = collapse(plain(text).replace(/[^a-z]/g, ''));
  if (HATE_ANY_C.some((h) => all.includes(h))) return true;
  return tokens(text).some((t) => HATE_WORD_RE.test(t.word));
}

const CRUDE_ANY_C = CRUDE_ANY.map(collapse);
function crudeWord(word) {
  const w = collapse(word);
  return CRUDE_ANY_C.some((c) => w.includes(c)) || CRUDE_WORD_RE.test(word);
}

const LINK = [
  /\bhttps?:\/\/\S+/gi,
  /\bwww\s*[.,]\s*\S+/gi,
  /\b[a-z0-9-]{2,}\s*(?:\.|\(dot\)|\[dot\]|\sdot\s)\s*(?:com|net|org|io|gg|tv|co|uk|xyz|me|ly|app|link|ru|de|fr|info|biz|online|site|club|live|to|us|be|ca|au|eu|dev|fun|games?)\b(?:\/\S*)?/gi,
  /\bdiscord\s*\.?\s*gg\s*\/\s*\S+/gi,
];
const CONTACT = [
  /[a-z0-9._%+-]+\s*(?:@|\(at\)|\[at\]|\sat\s)\s*[a-z0-9.-]+\s*(?:\.|\(dot\)|\[dot\]|\sdot\s)\s*[a-z]{2,}/gi, // emails
  /(?:\+?\d[\s\-.()]*){7,}\d/g, // phone numbers
  /(?:^|\s)@[a-z0-9_.]{2,}/gi, // @handles
  /\b(?:snap(?:chat)?|insta(?:gram)?|ig|discord|whats\s*app|telegram|tiktok|kik|skype|twitter|facebook|fb|psn|xbox|steam|epic|roblox)\s*(?:id|name|tag|is|me|:|-|=)*\s*[:\-=]?\s*[a-z0-9_.#]{3,}/gi,
  /\badd\s+me\s+(?:on|at)\b[^.!?]*/gi,
];

/**
 * Filter one chat message.
 * @returns {{ text: string, blocked: boolean, flags: { hate: boolean, crude: boolean, link: boolean, contact: boolean } }}
 */
export function filterChat(input) {
  let text = String(input ?? '')
    .replace(/./gsu, (c) => (invisible(c.codePointAt(0)) ? '' : c))
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, MAX_LENGTH);
  const flags = { hate: false, crude: false, link: false, contact: false };
  if (!text) return { text: '', blocked: true, flags };
  if (hasHate(text)) {
    flags.hate = true;
    return { text: '', blocked: true, flags };
  }
  const contact = (m) => {
    flags.contact = true;
    return (m.startsWith(' ') ? ' ' : '') + '[removed]';
  };
  // Emails first (they also look like links), then links, then other contacts.
  text = text.replace(CONTACT[0], contact);
  for (const re of LINK)
    text = text.replace(re, () => {
      flags.link = true;
      return '[link removed]';
    });
  for (const re of CONTACT.slice(1)) text = text.replace(re, contact);
  // Crude words: mask each offending word, keeping its length.
  const toks = tokens(text).filter((t) => crudeWord(t.word));
  if (toks.length) {
    flags.crude = true;
    let out = '';
    let at = 0;
    for (const t of toks) {
      out += text.slice(at, t.start) + text.slice(t.start, t.end).replace(/[^\s]/g, '*');
      at = t.end;
    }
    text = out + text.slice(at);
  }
  return { text, blocked: false, flags };
}

// How much a message counts towards a chat mute (3 within 15 minutes = muted).
export function strikeWeight(flags) {
  if (flags.hate) return 2;
  return flags.link || flags.contact || flags.crude ? 1 : 0;
}

